def summarize(values):
    count = len(values)
    total = sum(values)
    return {'count': count, 'total': total, 'average': total / count}

files.test_stats.py:
import unittest
from src.stats import summarize

class StatsTests(unittest.TestCase):
    def test_regular(self): self.assertEqual(summarize([5, 10, 15]), {'count': 3, 'total': 30, 'average': 10.0, 'min': 5, 'max': 15})
    def test_empty(self): self.assertEqual(summarize([]), {'count': 0, 'total': 0, 'average': 0.0, 'min': None, 'max': None})
    def test_mixed(self): self.assertEqual(summarize([-3, 0, 9]), {'count': 3, 'total': 6, 'average': 2.0, 'min': -3, 'max': 9})
    def test_single(self): self.assertEqual(summarize([7]), {'count': 1, 'total': 7, 'average': 7.0, 'min': 7, 'max': 7})

if __name__ == '__main__':
    unittest.main()
